std::string native_unicode_lower(const std::string& input){if(native_utf8_replace(input)!=input)fail(kExitInput,"Search is not UTF-8");std::vector<uint32_t> code;for(size_t i=0;i<input.size();){uint8_t c=input[i++];unsigned n=c<128?0:c<224?1:c<240?2:3;uint32_t cp=c& (n?((1u<<(6-n))-1):127);while(n--)cp=(cp<<6)|(uint8_t(input[i++])&63);code.push_back(cp);}std::string out;out.reserve(input.size());for(size_t i=0;i<code.size();++i){auto cp=code[i];if(cp==0x3a3){size_t p=i,q=i+1;while(p&&native_in_ranges(code[p-1],native_ignored_ranges))--p;while(q<code.size()&&native_in_ranges(code[q],native_ignored_ranges))++q;if(p&&native_in_ranges(code[p-1],native_cased_ranges)&&(q==code.size()||!native_in_ranges(code[q],native_cased_ranges))){native_utf8_append(out,0x3c2);continue;}}auto found=std::lower_bound(std::begin(native_lower_map),std::end(native_lower_map),cp,[](const NativeLowerEntry& a,uint32_t b){return a.code<b;});if(found!=std::end(native_lower_map)&&found->code==cp){for(size_t n=0;n<found->count;++n)native_utf8_append(out,native_lower_values[found->offset+n]);}else native_utf8_append(out,cp);}return out;}
